pub(crate) fn action_abi_digest_for_run_action(
    &self,
    run: RunId,
    action: ActionId,
) -> RuntimeResult<WorkflowDigest> {
    let state = self
        .run_state_get(run)
        .ok_or_else(|| RuntimeError::RunNotFound)?;
    // Find the contract for this action
